import '../data/motivation_library.dart';

/// A display-only fallback for imported media with autogenerated titles.
/// Original names, playback metadata and on-device files are never modified.
class MotivationDisplayTitle {
  const MotivationDisplayTitle._();

  static String of(MotivationTrack track) =>
      forName(track.title, isVideo: track.isVideo);

  static String forName(String original, {required bool isVideo}) {
    if (looksTechnical(original)) {
      return isVideo ? 'Video sin título' : 'Audio sin título';
    }
    return original.trim();
  }

  static bool looksTechnical(String name) {
    final value = name.trim();
    if (value.isEmpty) return true;
    final compact = value.replaceAll(RegExp(r'[-_]'), '');
    if (RegExp(r'^[0-9a-f]{20,}$', caseSensitive: false).hasMatch(compact)) {
      return true;
    }
    if (RegExp(r'^(?:img|vid|mvi|mov|aud|pxl)[_-]?\d{8,}[a-z0-9_-]*$',
        caseSensitive: false).hasMatch(value)) {
      return true;
    }
    // Opaque download names such as v14044g50000dadr..., not human phrases.
    if (value.length >= 16 &&
        RegExp(r'^[a-z0-9_-]+$', caseSensitive: false).hasMatch(value)) {
      final letters = RegExp(r'[a-z]', caseSensitive: false)
          .allMatches(value).length;
      final digits = RegExp(r'\d').allMatches(value).length;
      if (letters >= 4 && digits >= 5) return true;
    }
    return false;
  }
}
